"""A familiar word front, ordinary uses on its back, then a phrase companion."""
import json
import shutil
from pathlib import Path

from design_preview import CARDS, OUT
from design_preview_normal import RANKS

ROOT = Path(__file__).resolve().parents[2]

HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Portuguese · word then phrases</title>
<link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;600;700&family=Space+Grotesk:wght@600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css">
<style>
:root{--accent-primary:#67bf85;--ui-zoom:1}body{height:auto;min-height:100vh;overflow:auto;padding:24px 14px;user-select:auto}.preview-shell{max-width:940px;margin:auto}.preview-title{font:600 17px var(--font-emphasis);margin:0 0 6px}.preview-note{font-size:13px;color:var(--text-muted);margin-bottom:16px}.preview-picker{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:22px}.preview-picker button,.view-button{font:600 14px var(--font-reading);padding:7px 14px;border-radius:20px;border:1px solid var(--border-light);background:var(--bg-tertiary);color:var(--text-primary);cursor:pointer}.preview-picker button[aria-pressed=true]{color:var(--accent-primary);border-color:var(--accent-primary)}.preview-layout{display:flex;gap:26px;justify-content:center;align-items:flex-start}.study-stage{width:568px;max-width:100%;flex-shrink:0}.study-stage .card-replica{width:100%;--replica-card-h:580px}.study-stage .card-front{cursor:pointer}.study-stage .front-lemma-name{display:none}.study-stage .card-back{padding:22px 18px}.study-stage .card-details{padding:0!important;display:block!important;flex:0 0 auto;overflow:visible;height:auto;max-height:none}.use-box strong,.phrase-head strong{color:var(--text-primary)}.study-head{margin-bottom:18px;text-align:center}.study-word{font:700 42px/1.1 var(--font-emphasis)}.study-step{font:500 12px var(--font-reading);color:var(--text-muted);margin-top:9px}.study-step span{padding:3px 8px;border-radius:12px}.study-step .active-step{background:var(--bg-tertiary);color:var(--text-primary)}.use-stack{display:grid;gap:8px}.use-box{background:rgba(var(--sense-match-rgb),.09);border:1px solid rgba(var(--sense-match-rgb),.28);border-radius:9px;padding:11px 14px;text-align:center}.use-box strong{font:700 21px var(--font-reading);display:block}.use-box p{font-size:13px;color:var(--text-muted);line-height:1.4;margin-top:4px}.use-kind{font:600 11px var(--font-reading);color:rgb(var(--sense-match-rgb));margin-bottom:4px}.study-stage .sentence{--sense-match-rgb:103,191,133;margin-top:17px;padding:15px 16px!important;border-color:transparent!important}.study-stage .breakdown-trigger{font-size:21px!important;cursor:default}.study-stage .translation{font-size:15px!important}.study-stage .example-word-highlight{color:var(--accent-primary)!important}.sequence-control{display:block;width:100%;border:1px solid var(--border-light);border-radius:9px;padding:11px;background:var(--bg-tertiary);font:600 14px var(--font-reading);color:var(--text-primary);cursor:pointer;margin-top:17px}.sequence-control .arrow{color:var(--accent-primary);margin-left:8px}.small-back{color:var(--text-muted);font:500 13px var(--font-reading);background:none;border:0;padding:8px 0;cursor:pointer;text-align:left}.phrase-row{border:1px solid #554c6d;background:rgba(167,139,250,.07);border-radius:10px;padding:14px 16px}.phrase-row+ .phrase-row{margin-top:10px}.phrase-head{display:flex;gap:10px;justify-content:space-between;align-items:baseline}.phrase-head strong{font:700 22px var(--font-reading)}.phrase-head span{color:#d5c5f3;font-size:18px}.phrase-row p{font-size:13px;color:var(--text-muted);margin-top:6px}.phrases-intro{font-size:14px;color:var(--text-muted);text-align:center;margin:0 0 17px}.parts{display:flex;gap:8px;justify-content:center;align-items:center;margin:12px 0 15px}.parts span{border:1px solid var(--border-light);background:var(--bg-tertiary);border-radius:8px;padding:5px 12px;font-size:14px}.preview-aside{width:190px;color:var(--text-muted);font-size:13px;line-height:1.5;padding-top:10px}.preview-aside p{margin-bottom:15px}.preview-aside b{color:var(--text-primary)}.preview-aside button{margin:4px 0;width:100%;text-align:left}.front-control{display:block;margin:12px auto 0;font:600 13px var(--font-reading);color:var(--text-muted);background:none;border:0;cursor:pointer;padding:8px}button:focus-visible{outline:2px solid var(--accent-primary);outline-offset:4px}
@media(max-width:760px){body{padding:16px 8px}.preview-layout{display:block}.study-stage{width:100%;max-width:568px;margin:auto}.study-stage .card-replica{--replica-card-h:580px}.study-stage .card-back{padding:18px 14px}.study-word{font-size:38px}.use-box{padding:10px 12px}.use-box strong{font-size:19px}.use-box p{font-size:12px}.study-stage .breakdown-trigger{font-size:19px!important}.study-stage .translation{font-size:14px!important}.phrase-head{flex-wrap:wrap;gap:3px 10px}.phrase-head strong{font-size:20px}.phrase-head span{font-size:17px}.preview-aside{width:auto;margin:18px 6px 0}.preview-aside .view-button{width:auto;margin-right:6px}.preview-picker{gap:5px;margin-bottom:16px}.preview-picker button{padding:6px 11px;font-size:13px}.preview-note{font-size:12px;line-height:1.4}}
</style></head><body><main class="preview-shell"><h1 class="preview-title">Portuguese · word, then phrases</h1><p class="preview-note">Design example. Real word rank and frequency; existing sentences and translations unchanged. No learner progress or assignments are changed.</p><nav class="preview-picker" id="picker" aria-label="Choose a Portuguese draft"></nav><div class="preview-layout"><div class="study-stage" id="stage"></div><aside class="preview-aside"><p><b>1. Familiar front</b><br>The word, part of speech, vocabulary rank and frequency.</p><p><b>2. Word back</b><br>The ordinary uses by themselves, with the existing example.</p><p><b>3. Phrase companion</b><br>A small set of useful combinations follows. Its boxes fit the phrases.</p><button class="view-button" data-view="front">Show word front</button><button class="view-button" data-view="back">Show word back</button><button class="view-button" data-view="phrases" id="phrase-jump">Show phrase card</button></aside></div></main>
<script type="module">
import {renderFront,highlightWord,esc,posAccentRgb} from './assets/js/card-replica.js';
const cards=__CARDS__,examples=__EXAMPLES__,ranks=__RANKS__,frequency=__FREQUENCY__;
const types={que:['CONJ','PRON','CONJ'],de:['PREP'],se:['CONJ','PRON','PRON'],o:['ARTICLE','PRON'],nos:['PRON','PRON','CONTRACTION'],naquele:['CONTRACTION']};const names={CONJ:'conjunction',PRON:'pronoun',PREP:'preposition',ARTICLE:'article',CONTRACTION:'contraction'};let word='que',view='front';
cards.se.phrases=[{text:'lembrar-se',english:'remember',note:'Often followed by de.'},{text:'esquecer-se',english:'forget',note:'Often followed by de.'},{text:'preocupar-se',english:'worry',note:'Often followed by com.'}];
const frameNotes={'o que':'what someone asks about or refers to','ter que':'ter que + verb','assim que':'followed by a clause','gostar de':'gostar de + something','precisar de':'precisar de + something','ter de':'ter de + verb'};
function render(){const d=cards[word],e=examples[word],hasPhrases=d.phrases.length>0;document.querySelectorAll('[data-word]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.word===word)));document.getElementById('phrase-jump').hidden=!hasPhrases;const model={mode:'speech',word,lemma:word,pos:types[word][0],rank:ranks[word],vocabSize:10000,corpusCount:frequency[word],lookup:[],rareUses:[],meanings:[]};const header=`<div class="study-head"><div class="study-word">${esc(word)}</div>${hasPhrases?`<div class="study-step"><span class="${view==='phrases'?'':'active-step'}">Word</span> → <span class="${view==='phrases'?'active-step':''}">Phrases</span></div>`:''}</div>`;
const main=view==='phrases'?`${header}<p class="phrases-intro">Useful combinations with ${esc(word)}</p>${d.phrases.map(p=>`<div class="phrase-row"><div class="phrase-head"><strong>${esc(p.text)}</strong><span>${esc(p.english)}</span></div>${p.note||frameNotes[p.text]?`<p>${esc(p.note||frameNotes[p.text])}</p>`:''}</div>`).join('')}<button class="small-back" data-view="back">← Back to the word</button>`:`${header}${d.parts&&word!=='nos'?`<div class="parts" aria-label="${word==='nos'?'Contraction use':'Parts of the contraction'}">${d.parts.map(p=>`<span>${esc(p)}</span>`).join('+')}</div>`:''}<div class="use-stack">${d.uses.map((u,i)=>`<div class="use-box" style="--sense-match-rgb:${posAccentRgb(types[word][i])}"><div class="use-kind">${esc(names[types[word][i]])}</div><strong>${esc(u.english)}</strong><p>${esc(u.description)}</p></div>`).join('')}</div><div class="sentence"><div class="breakdown-trigger">${highlightWord(e.text,word)}</div><div class="translation">${esc(e.english)}</div></div>${hasPhrases?`<button class="sequence-control" data-view="phrases">Next: phrases with ${esc(word)} <span class="arrow">→</span></button>`:''}`;
document.getElementById('stage').innerHTML=view==='front'?`<div class="card-replica"><div class="card">${renderFront(model)}</div></div><button class="front-control" data-view="back">Flip to the word’s uses</button>`:`<div class="card-replica"><div class="card flipped"><div class="card-face card-back"><div class="card-details">${main}</div></div></div></div><button class="front-control" data-view="front">Show front</button>`;
const front=document.querySelector('.card-front');if(front){front.querySelector('.front-lemma-name')?.remove();const pill=front.querySelector('.card-pos-list');pill.innerHTML=[...new Set(types[word])].map(p=>`<span class="front-lemma-pair"><span class="front-pos-unit"><span class="card-pos pos-${p==='CONJ'?'conj':p==='PRON'?'pron':p==='ARTICLE'?'det':p==='PREP'?'prep':'contraction'}">${esc(names[p])}</span></span></span>`).join('');front.addEventListener('click',()=>{view='back';render()})}else{const details=document.querySelector('.card-details');requestAnimationFrame(()=>{const face=details.closest('.card-back'),css=getComputedStyle(face);details.closest('.card-replica').style.setProperty('--replica-card-h',Math.max(520,details.scrollHeight+parseFloat(css.paddingTop)+parseFloat(css.paddingBottom)+12)+'px')})}}
document.getElementById('picker').innerHTML=Object.keys(cards).map(w=>`<button type="button" data-word="${w}" aria-pressed="false">${w}</button>`).join('');document.addEventListener('click',e=>{const wordButton=e.target.closest('[data-word]'),viewButton=e.target.closest('[data-view]');if(wordButton){word=wordButton.dataset.word;view='front';render()}else if(viewButton){view=viewButton.dataset.view;render()}});render();
</script></body></html>'''


def main():
    config = json.loads((ROOT / "app/config/config.json").read_text())
    source = json.loads((ROOT / "app" / config["languages"]["portuguese"]["frequencyPath"]).read_text())
    frequency = {word: source["values"][word] for word in CARDS}
    examples = json.loads((OUT / "examples.json").read_text())
    shutil.copy2(OUT / "index.html", OUT / "index-normal.html")
    payload = HTML
    for name, value in (("CARDS", CARDS), ("EXAMPLES", examples), ("RANKS", RANKS), ("FREQUENCY", frequency)):
        payload = payload.replace("__" + name + "__", json.dumps(value, ensure_ascii=False))
    (OUT / "index.html").write_text(payload)
    print(OUT / "index.html")


if __name__ == "__main__":
    main()
